CREATE TYPE "DrDrillStatus" AS ENUM ('PLANNED','RUNNING','PASSED','PASSED_WITH_FINDINGS','FAILED','CANCELED');
CREATE TYPE "DrFindingStatus" AS ENUM ('OPEN','IN_PROGRESS','RESOLVED','ACCEPTED');
CREATE TABLE "DrDrill" ("id" TEXT NOT NULL,"type" TEXT NOT NULL,"environment" TEXT NOT NULL,"plannedAt" TIMESTAMP(3),"performedAt" TIMESTAMP(3),"ownerId" TEXT,"status" "DrDrillStatus" NOT NULL DEFAULT 'PLANNED',"rpoStatus" TEXT NOT NULL DEFAULT 'UNKNOWN',"rtoStatus" TEXT NOT NULL DEFAULT 'UNKNOWN',"rpoTargetSeconds" INTEGER,"rpoObservedSeconds" INTEGER,"rtoTargetSeconds" INTEGER,"rtoObservedSeconds" INTEGER,"incidentStartedAt" TIMESTAMP(3),"recoveryStartedAt" TIMESTAMP(3),"dbReadyAt" TIMESTAMP(3),"storageValidatedAt" TIMESTAMP(3),"webReadyAt" TIMESTAMP(3),"workerReadyAt" TIMESTAMP(3),"criticalValidatedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"findings" JSONB NOT NULL DEFAULT '{}',"actions" JSONB NOT NULL DEFAULT '{}',"nextDrillAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DrDrill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DrFinding" ("id" TEXT NOT NULL,"drillId" TEXT NOT NULL,"severity" TEXT NOT NULL,"component" TEXT NOT NULL,"description" TEXT NOT NULL,"action" TEXT NOT NULL,"ownerId" TEXT,"status" "DrFindingStatus" NOT NULL DEFAULT 'OPEN',"dueAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DrFinding_pkey" PRIMARY KEY ("id"));
CREATE INDEX "DrDrill_environment_status_plannedAt_idx" ON "DrDrill"("environment","status","plannedAt");
CREATE INDEX "DrFinding_status_severity_idx" ON "DrFinding"("status","severity");
CREATE INDEX "DrFinding_drillId_idx" ON "DrFinding"("drillId");
ALTER TABLE "DrFinding" ADD CONSTRAINT "DrFinding_drillId_fkey" FOREIGN KEY ("drillId") REFERENCES "DrDrill"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
